"""Zero-assumptions computer, HTML, and CSS learning path."""


def modules(build_lesson):
    """Return additive beginner modules; lesson content is intentionally instructional."""
    curriculum = [
        {
            "title": "Start Here: Computer and Web Basics",
            "lessons": [
                build_lesson("Welcome: How to Learn Here", "start-here-how-to-learn", "<h2>Welcome — no experience needed</h2><p>This course starts with the basics and builds one small idea at a time. You do not need to know what a file, browser, or code editor is yet. Read the explanation, study the example, make the requested change, and look at the result.</p><h2>The learning loop</h2><ol><li><strong>Read:</strong> learn one idea and its new words.</li><li><strong>Notice:</strong> compare the example with the task.</li><li><strong>Try:</strong> make a small change yourself.</li><li><strong>Observe:</strong> use the preview and feedback to understand what happened.</li><li><strong>Repeat:</strong> change one thing at a time. Mistakes are useful clues.</li></ol><p>Your work is saved in this browser while you type. Passing a lesson saves completion to your account. Revisit lessons whenever you need them.</p>", "<h1>Welcome</h1>\n<p>I can learn step by step.</p>", "<h1>Welcome</h1>", tests=[{"test": "code.includes('<h1') && code.includes('<p')", "message": "Keep both a heading and a paragraph in your first page."}], hints=["A heading uses h1 tags.", "A paragraph uses p tags.", "Put words between each opening and closing tag."]),
                build_lesson("What Is a Computer? Input, Processing, Storage, and Output", "start-here-computer-basics", "<h2>A computer follows instructions</h2><p>A computer takes in information, follows instructions to work with it, stores information, and shows or sends a result. These ideas are input, processing, storage, and output.</p><ul><li><strong>Input:</strong> a keyboard, mouse, microphone, or touchscreen gives information.</li><li><strong>Processing:</strong> the processor carries out instructions.</li><li><strong>Storage:</strong> a drive keeps files when the computer is off.</li><li><strong>Output:</strong> a screen, speaker, or printer presents a result.</li></ul><h2>Hardware and software</h2><p>Hardware is physical equipment. Software is the instructions and applications that run on it. Your browser and code editor are software. The operating system, such as Windows, macOS, or Linux, helps software use the hardware.</p><p>When you type code, the keyboard is input; the editor shows it; saving writes it to storage; the browser processes web files and displays the page.</p>", "<p>Keyboard: input</p>\n<p>Browser: software that displays web pages</p>\n<p>Saved files: storage</p>", "<p>Keyboard: input</p>\n<p>Browser: software that displays web pages</p>"),
                build_lesson("Use Your Mouse, Trackpad, Keyboard, and Shortcuts", "start-here-input-and-shortcuts", "<h2>Point, select, and type</h2><p>A mouse, trackpad, stylus, or touchscreen moves a pointer and selects things. A keyboard types text and commands. Most actions can also be done without a mouse, which is important for accessibility and can be faster.</p><ol><li>Click once to select or place the pointer.</li><li>Press <kbd>Tab</kbd> to move through buttons and links; <kbd>Enter</kbd> or <kbd>Space</kbd> activates the focused control.</li><li>Use <kbd>Ctrl</kbd>+<kbd>S</kbd> on Windows/Linux or <kbd>Cmd</kbd>+<kbd>S</kbd> on Mac to save.</li><li>Use <kbd>Ctrl</kbd>/<kbd>Cmd</kbd>+<kbd>Z</kbd> to undo a change.</li></ol><p>Shortcuts differ by app. If one does not work, use the visible menu command. Speed matters less than being able to undo and recover your work.</p>", "<p>Tab moves focus. Enter activates a focused link or button.</p>", "<p>Tab moves focus. Enter activates a focused link or button.</p>"),
                build_lesson("Files and Folders: Save and Find Your Work", "start-here-files-and-folders", "<h2>Files and folders</h2><p>A file is one saved item, such as a picture or page of code. A folder holds files and other folders to keep work organized. Filenames ending in <code>.html</code> usually contain page structure; <code>.css</code> contains styling; <code>.js</code> contains behavior.</p><h2>Save carefully</h2><ol><li>Choose a clear project folder.</li><li>Use descriptive names such as <code>index.html</code> and <code>styles.css</code>.</li><li>Save after meaningful changes. An unsaved indicator means your newest work may not be on disk yet.</li><li>If you cannot find a file, check the folder shown in the editor and search your computer.</li></ol><p>Do not delete a project folder to fix a problem. Make a copy before risky changes.</p>", "<ul>\n  <li>index.html — page structure</li>\n  <li>styles.css — page appearance</li>\n</ul>", "<ul>\n  <li>index.html — page structure</li>\n</ul>"),
                build_lesson("Browser, Website, Search Engine, and Internet", "start-here-browser-web-internet", "<h2>These words mean different things</h2><ul><li><strong>Internet:</strong> a worldwide network that lets computers communicate.</li><li><strong>Website:</strong> connected web pages and files published at an address.</li><li><strong>Browser:</strong> an app such as Edge, Chrome, Firefox, or Safari that requests and displays websites.</li><li><strong>Search engine:</strong> a service that helps people find pages.</li></ul><h2>What happens when a page opens?</h2><p>The browser requests files from a web server over the internet. The server sends them back. The browser reads HTML for structure, CSS for appearance, and JavaScript for behavior, then draws the result on screen. A website can also be practiced locally on your computer without publishing it.</p><p>A browser is a tool; a search engine is a service; the internet is the network connecting computers.</p>", "<p>Internet → connects devices</p>\n<p>Browser → displays a website</p>\n<p>Search engine → helps people find pages</p>", "<p>Internet → connects devices</p>\n<p>Browser → displays a website</p>"),
                build_lesson("Your First Developer Tools: Editor, Browser, and Documentation", "start-here-developer-tools", "<h2>Three tools are enough to begin</h2><ul><li><strong>Code editor:</strong> writes and saves text files. VS Code is one example; any plain-text editor can write HTML and CSS.</li><li><strong>Browser:</strong> displays your page. Developer tools can inspect it and show errors.</li><li><strong>Documentation:</strong> explains web standards. MDN Web Docs is a useful reference; search for a specific feature such as “MDN CSS color”.</li></ul><h2>A safe practice loop</h2><ol><li>Edit a small piece of code.</li><li>Save the file.</li><li>Refresh the browser page.</li><li>Compare what you expected with what you see.</li><li>If different, inspect spelling, punctuation, and the browser console.</li></ol><p>You do not have to memorize everything. Developers regularly look up details in reliable documentation.</p>", "<p>Edit → save → view in browser → inspect → improve</p>", "<p>Edit → save → view in browser → inspect → improve</p>"),
            ],
        },
        {
            "title": "HTML from Scratch: Build the Page Structure",
            "lessons": [
                build_lesson("What HTML Is and How a Web Page Is Built", "start-html-what-is-html", "<h2>HTML gives content structure and meaning</h2><p>HTML means HyperText Markup Language. It is not a programming language: it marks content so a browser can identify headings, paragraphs, links, images, lists, and other parts. CSS controls appearance; JavaScript can add behavior.</p><h2>Tags and elements</h2><p>A tag is markup such as <code>&lt;p&gt;</code>. An element usually includes an opening tag, content, and a closing tag: <code>&lt;p&gt;Hello&lt;/p&gt;</code>. The whole thing is a paragraph element. Some elements, such as <code>&lt;img&gt;</code>, do not wrap text and have no closing tag.</p><h2>How the browser reads it</h2><p>The browser reads the HTML text and builds a document tree called the DOM. It applies default styles, so headings and links already look different before you write CSS. Start by changing content, not memorizing every tag.</p>", "<h1>My first page</h1>\n<p>This is a paragraph.</p>", "<h1>My first page</h1>"),
                build_lesson("Typing HTML: Brackets, Slashes, Quotes, and Indentation", "start-html-typing-basics", "<h2>HTML is ordinary text with a few special characters</h2><p>You type HTML in a code editor just like a document. A tag starts with a less-than sign <code>&lt;</code> and ends with a greater-than sign <code>&gt;</code>. A closing tag has a forward slash <code>/</code> just after the opening bracket. For example, a paragraph begins with <code>&lt;p&gt;</code> and ends with <code>&lt;/p&gt;</code>.</p><h2>Build one line carefully</h2><ol><li>Type the opening tag, including both angle brackets.</li><li>Type the words the visitor should see.</li><li>Type the closing tag with its slash.</li><li>Press Enter to put the next element on a new line.</li><li>Indent nested elements with Tab or spaces so the structure is easy to read.</li></ol><h2>Attributes use quotes</h2><p>When an opening tag needs extra information, type a space, the attribute name, an equals sign, and quotation marks. Example pattern: <code>&lt;a href=&quot;address&quot;&gt;link words&lt;/a&gt;</code>. Put the destination between the quotes, not outside them.</p><h2>Common typing mistakes</h2><ul><li>Using a backslash <code>\\</code> instead of the forward slash <code>/</code> in a closing tag.</li><li>Forgetting one angle bracket or a closing tag.</li><li>Putting visible words inside the tag name rather than between opening and closing tags.</li><li>Using curly “smart quotes” in code instead of plain straight quotes <code>&quot;</code>.</li></ul><p>If the preview looks wrong, check one character at a time. The editor does not need special formatting; correct characters and nesting are what matter.</p>", "<p>Practice typing a paragraph with opening and closing tags.</p>", "<p>Type your own paragraph here.</p>", tests=[{"test": "code.includes('<p>') && code.includes('</p>')", "message": "Type both the opening and closing paragraph tags."}, {"test": "code.indexOf('<p>') < code.indexOf('</p>')", "message": "Place your text between the opening and closing tags."}], hints=["Start with <p>.", "Write your sentence after the opening tag.", "Finish with </p> - the slash goes inside the angle brackets."]),
                build_lesson("The HTML Document: Doctype, html, head, and body", "start-html-document-skeleton", "<h2>Every page has a useful outer structure</h2><p><code>&lt;!DOCTYPE html&gt;</code> tells the browser to use modern HTML. <code>&lt;html lang=\"en\"&gt;</code> wraps the document and identifies its language. <code>&lt;head&gt;</code> contains page information such as title and character encoding. <code>&lt;body&gt;</code> contains visible content.</p><h2>Build in this order</h2><ol><li>Start with the doctype.</li><li>Open html and set its language.</li><li>Put metadata and a title in head.</li><li>Put headings, text, links, and images in body.</li><li>Close body and html in reverse order.</li></ol><p>Indentation helps people see nesting. Correct nesting matters more than the exact number of spaces.</p>", "<!doctype html>\n<html lang=\"en\">\n  <head>\n    <meta charset=\"utf-8\">\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n    <title>My First Page</title>\n  </head>\n  <body>\n    <h1>Hello, web!</h1>\n  </body>\n</html>", "<!doctype html>\n<html lang=\"en\">\n  <head>\n    <meta charset=\"utf-8\">\n    <title>My First Page</title>\n  </head>\n  <body>\n    <h1>Hello, web!</h1>\n  </body>\n</html>", tests=[{"test": "code.toLowerCase().includes('<!doctype html>')", "message": "Include the HTML doctype."}, {"test": "code.includes('<head>') && code.includes('<body>')", "message": "Separate page information from visible content."}, {"test": "code.includes('<title>')", "message": "Give the document a title."}]),
                build_lesson("Headings and Paragraphs: Make Text Easy to Read", "start-html-headings-paragraphs", "<h2>Use headings as an outline</h2><p>Use one main <code>&lt;h1&gt;</code> for the page topic, then <code>&lt;h2&gt;</code> for major sections and <code>&lt;h3&gt;</code> for a subsection within one. Choose a heading level because of its place in the outline, not its default size.</p><p>Use <code>&lt;p&gt;</code> for a paragraph. Use <code>&lt;strong&gt;</code> for important text and <code>&lt;em&gt;</code> for emphasis; these tags communicate meaning as well as appearance.</p><h2>Common mistakes</h2><ul><li>Using headings only to make text large; CSS controls appearance.</li><li>Skipping heading levels without a structural reason.</li><li>Putting unrelated ideas into one very long paragraph.</li></ul>", "<h1>My Garden</h1>\n<p>I grow vegetables at home.</p>\n<h2>What I grow</h2>\n<p>Tomatoes and herbs are my favorites.</p>", "<h1>My Garden</h1>\n<p>I grow vegetables at home.</p>\n<h2>What I grow</h2>", tests=[{"test": "code.includes('<h1') && code.includes('</h1>')", "message": "Add a main page heading."}, {"test": "code.includes('<h2') && code.includes('</h2>')", "message": "Add a section heading."}, {"test": "(code.match(/<p\\b/g) || []).length >= 2", "message": "Use paragraphs to group the text."}]),
                build_lesson("Attributes: Add Details to Elements", "start-html-attributes", "<h2>Attributes provide extra information</h2><p>An attribute is written in an opening tag. It has a name and usually a quoted value, such as <code>&lt;a href=\"https://example.com\"&gt;</code>. Here, href tells the browser where the link goes.</p><ul><li><code>id</code> identifies one unique element on a page.</li><li><code>class</code> gives elements a reusable label, often used by CSS.</li><li><code>href</code> sets a link destination.</li><li><code>src</code> points to a media file.</li><li><code>alt</code> provides an image text alternative.</li></ul><p>Separate attributes with spaces and quote text values. The dot in a CSS class selector is not written in the HTML class value.</p>", "<p class=\"intro\" id=\"welcome\">Welcome to my site.</p>", "<p class=\"intro\">Welcome to my site.</p>", tests=[{"test": "code.includes('class=')", "message": "Add a reusable class attribute."}, {"test": "code.includes('<p') && code.includes('</p>')", "message": "Keep a complete paragraph."}]),
                build_lesson("Links: Connect Pages with Clear Destinations", "start-html-links", "<h2>An anchor creates a link</h2><p>Use an <code>&lt;a&gt;</code> element to link to another page or a location on the same page. Its <code>href</code> stores the destination. The words between the tags should explain where the link leads, such as “Read the course outline,” rather than an unclear “click here.”</p><p>A full address can start with <code>https://</code>. A relative destination can point to another project file. A fragment such as <code>#contact</code> points to an element whose id is contact.</p><p>Link to destinations you trust, and make link text understandable when read on its own.</p>", "<a href=\"https://developer.mozilla.org/\">Read MDN Web Docs</a>", "<a href=\"https://developer.mozilla.org/\">Read MDN Web Docs</a>", tests=[{"test": "code.includes('<a ') && code.includes('href=')", "message": "Create a link with a destination."}, {"test": "code.includes('</a>')", "message": "Close the link after its descriptive text."}]),
                build_lesson("Images: Source, Size, and Alternative Text", "start-html-images", "<h2>Add an image responsibly</h2><p>The <code>&lt;img&gt;</code> element displays an image. <code>src</code> gives the file address. <code>alt</code> describes useful information for people who cannot see the image or if the file fails to load. An image is a void element and has no closing tag.</p><p>Write useful alt text for meaningful images. Use empty alt (<code>alt=\"\"</code>) for purely decorative images so screen readers can skip them. Never omit alt. Keep image files organized and name them accurately.</p><p>CSS can make images responsive. Avoid dimensions that stretch an image out of proportion.</p>", "<img src=\"images/bicycle.jpg\" alt=\"Red bicycle parked beside a brick wall\">", "<img src=\"images/bicycle.jpg\" alt=\"Red bicycle\">", tests=[{"test": "code.includes('<img') && code.includes('src=')", "message": "Add an image with a source."}, {"test": "code.includes('alt=')", "message": "Provide an alt text value."}]),
                build_lesson("Lists: Group Items in a Useful Order", "start-html-lists", "<h2>Choose the list that matches the meaning</h2><p>Use <code>&lt;ul&gt;</code> when order does not matter, such as a shopping list. Use <code>&lt;ol&gt;</code> when sequence matters, such as instructions. Put every item in <code>&lt;li&gt;</code> inside the list. Do not imitate a list with repeated paragraphs or typed dashes.</p><p>List items belong inside their ul or ol. Indent nested elements so you can see the structure. A list item can contain links or other content when appropriate.</p>", "<h2>My learning plan</h2>\n<ol>\n  <li>Learn HTML</li>\n  <li>Practice CSS</li>\n  <li>Build a page</li>\n</ol>", "<h2>My learning plan</h2>\n<ol>\n  <li>Learn HTML</li>\n</ol>", tests=[{"test": "code.includes('<ol') && code.includes('</ol>')", "message": "Create a complete ordered list."}, {"test": "(code.match(/<li\\b/g) || []).length >= 3", "message": "Add three ordered steps."}]),
                build_lesson("Semantic HTML: Header, Nav, Main, Section, and Footer", "start-html-semantic-structure", "<h2>Choose elements by their purpose</h2><p>Semantic HTML communicates what each region means. <code>&lt;header&gt;</code> introduces a page or section. <code>&lt;nav&gt;</code> contains important navigation links. <code>&lt;main&gt;</code> holds the primary content and is usually used once. <code>&lt;section&gt;</code> groups a theme, usually with a heading. <code>&lt;article&gt;</code> is a self-contained item. <code>&lt;footer&gt;</code> contains closing information.</p><p>Use a generic <code>&lt;div&gt;</code> only when no meaningful element fits. Semantics help people, assistive technology, maintainers, and search engines understand structure.</p><p>Ask “What is this region for?” Choose an element whose purpose matches. Do not use semantic tags only to change appearance.</p>", "<header><h1>My Portfolio</h1></header>\n<nav><a href=\"#work\">My work</a></nav>\n<main>\n  <section id=\"work\"><h2>Projects</h2><p>Things I have made.</p></section>\n</main>\n<footer><p>Contact me</p></footer>", "<header><h1>My Portfolio</h1></header>\n<main>\n  <section><h2>Projects</h2><p>Things I have made.</p></section>\n</main>", tests=[{"test": "code.includes('<header')", "message": "Add a page introduction region."}, {"test": "code.includes('<main')", "message": "Mark the primary content."}, {"test": "code.includes('<section') && code.includes('<h2')", "message": "Add a titled section."}]),
                build_lesson("Forms: Labels, Inputs, and Buttons", "start-html-forms", "<h2>Forms collect information</h2><p>A <code>&lt;form&gt;</code> groups controls. Connect a <code>&lt;label&gt;</code> to its control using matching <code>for</code> and <code>id</code> values. This gives the control an accessible name and makes the label clickable.</p><p>Choose an input type that describes the data, such as email or text. Give buttons a clear purpose and use <code>type=\"submit\"</code> to submit a form. A placeholder is an example, not a replacement for a label.</p><p>A real form needs server-side or application logic to validate and handle submitted data; HTML alone does not store it.</p>", "<form>\n  <label for=\"email\">Email address</label>\n  <input id=\"email\" name=\"email\" type=\"email\">\n  <button type=\"submit\">Join the list</button>\n</form>", "<form>\n  <label for=\"email\">Email address</label>\n  <input id=\"email\" name=\"email\" type=\"email\">\n</form>", tests=[{"test": "code.includes('<form') && code.includes('</form>')", "message": "Wrap the controls in a form."}, {"test": "code.includes('for=') && code.includes('id=')", "message": "Connect the visible label to the input."}, {"test": "code.includes('type=\"email\"')", "message": "Use the email input type."}]),
                build_lesson("Tables: Show Data with Row and Column Headings", "start-html-tables", "<h2>Tables are for data, not page layout</h2><p>Use <code>&lt;table&gt;</code> for information organized into rows and columns. <code>&lt;caption&gt;</code> describes the table. Put a row in <code>&lt;tr&gt;</code>, use <code>&lt;th&gt;</code> for a heading cell, and <code>&lt;td&gt;</code> for data. Use <code>&lt;thead&gt;</code> and <code>&lt;tbody&gt;</code> to group sections when helpful.</p><p>Keep tables simple and make the relationship between headers and data clear. Do not use tables to lay out ordinary page content; CSS layout tools are for that.</p>", "<table>\n  <caption>My weekly study plan</caption>\n  <thead><tr><th scope=\"col\">Day</th><th scope=\"col\">Topic</th></tr></thead>\n  <tbody><tr><td>Monday</td><td>HTML</td></tr></tbody>\n</table>", "<table>\n  <caption>My weekly study plan</caption>\n  <tr><th scope=\"col\">Day</th><th scope=\"col\">Topic</th></tr>\n  <tr><td>Monday</td><td>HTML</td></tr>\n</table>", tests=[{"test": "code.includes('<table') && code.includes('</table>')", "message": "Create a complete table."}, {"test": "code.includes('<th')", "message": "Mark the column headings."}, {"test": "code.includes('<td')", "message": "Add a data cell."}]),
            ],
        },
        {
            "title": "CSS from Scratch: Style the Page",
            "lessons": [
                build_lesson("What CSS Does: From Plain Page to Design", "start-css-what-css-does", "<h2>HTML and CSS have different jobs</h2><p>HTML describes what content is and how it is structured. CSS means Cascading Style Sheets; it describes presentation: color, type, spacing, borders, and layout. Browsers also have default styles, which is why an unstyled heading is already larger than a paragraph.</p><h2>How styles reach the screen</h2><p>The browser reads HTML and builds a document tree. CSS rules select elements in that tree. The browser calculates applicable styles and paints the result. In this lesson, the preview updates while you edit CSS.</p><p>Change one property, observe the preview, and explain what changed. CSS is a rule-based language; you can look up unfamiliar properties rather than memorize them.</p>", "body {\n  font-family: Arial, sans-serif;\n}\n\nh1 {\n  color: #2563eb;\n}", "body {\n  font-family: Arial, sans-serif;\n}", language="css", tests=[{"test": "code.includes('body') && code.includes('font-family')", "message": "Choose a readable page font."}, {"test": "code.includes('h1') && code.includes('color')", "message": "Give the heading a color."}], hints=["Start a body rule with curly braces.", "Put font-family inside the body rule.", "Create another rule for h1 and set color."]),
                build_lesson("CSS Rule Anatomy: Selector, Property, and Value", "start-css-rule-anatomy", "<h2>Read a CSS rule from left to right</h2><p>In <code>p { color: navy; }</code>, <code>p</code> is the selector: it chooses elements. Braces hold the declaration block. <code>color</code> is the property (what to change), and <code>navy</code> is the value (how to change it). The colon separates property and value; the semicolon ends the declaration.</p><ol><li>Write the selector.</li><li>Open a brace.</li><li>Write a property, colon, value, and semicolon.</li><li>Close the brace.</li><li>Inspect the preview.</li></ol><p>One rule can contain multiple declarations. Put each on its own line so mistakes are easier to find. A missing brace can affect more of the stylesheet than intended.</p>", "h1 {\n  color: navy;\n  font-size: 2rem;\n}", "h1 {\n  color: navy;\n}", language="css", tests=[{"test": "code.includes('h1')", "message": "Select the main heading."}, {"test": "code.includes('color:')", "message": "Add a color property and value."}, {"test": "code.includes('font-size:')", "message": "Add a second declaration."}]),
                build_lesson("Selectors: Elements, Classes, and IDs", "start-css-selectors", "<h2>Choose which elements receive a rule</h2><p>A type selector such as <code>p</code> selects every paragraph. A class selector begins with a dot, such as <code>.card</code>, and matches HTML with <code>class=\"card\"</code>. Classes are reusable. An ID selector begins with <code>#</code> and targets a unique id.</p><p>Use type selectors for shared defaults, classes for reusable patterns, and IDs only for a unique target when appropriate. The dot and hash belong in CSS, not in the HTML attribute. HTML uses <code>class=\"card\"</code>; CSS uses <code>.card { ... }</code>.</p><p>If a selector does not match, compare its spelling and punctuation exactly with the HTML.</p>", ".card {\n  background-color: #eff6ff;\n}\n\n#notice {\n  color: #1d4ed8;\n}", ".card {\n  background-color: #eff6ff;\n}", language="css", tests=[{"test": "code.includes('.card')", "message": "Create a reusable class selector."}, {"test": "code.includes('background-color')", "message": "Give the card a background."}, {"test": "code.includes('#notice')", "message": "Add a selector for a unique notice."}]),
                build_lesson("Colors and Contrast: Make Content Readable", "start-css-colors-contrast", "<h2>Foreground and background</h2><p><code>color</code> sets text and foreground color. <code>background-color</code> sets a surface. Values can be named colors, hex such as <code>#1d4ed8</code>, RGB, or HSL.</p><h2>Readability comes first</h2><p>Text should be easy to distinguish from its background. Start with dark text on a light surface or the reverse, then check the actual contrast. Do not communicate meaning through color alone; pair color with words, shapes, or icons. Links should look like links.</p><p>Try a new value. If text becomes hard to read, choose stronger contrast.</p>", "body {\n  color: #172033;\n  background-color: #f8fafc;\n}\n\na {\n  color: #1d4ed8;\n}", "body {\n  color: #172033;\n}", language="css", tests=[{"test": "code.includes('color:')", "message": "Set a text color."}, {"test": "code.includes('background-color:')", "message": "Set a background surface."}, {"test": "code.includes('a') && code.includes('#1d4ed8')", "message": "Choose a link color."}]),
                build_lesson("CSS Values and Units: px, rem, %, and Unitless Numbers", "start-css-values-units", "<h2>Units explain what a number means</h2><p><code>px</code> is a CSS pixel and works for precise details such as a border. <code>rem</code> is relative to root text size and is useful for scalable text and spacing. <code>%</code> is relative to a containing size, often useful for flexible widths. Some values, such as <code>line-height: 1.5</code>, are intentionally unitless.</p><ul><li>Use rem for scalable text and spacing.</li><li>Use percentages or flexible constraints for adaptable widths.</li><li>Use px for precise details where appropriate.</li><li>Do not attach units to every number; check the property's expected value.</li></ul><p>A fixed pixel width can overflow a small screen. Combine flexible width with max-width when you need a readable line length.</p>", "body {\n  font-size: 1rem;\n  line-height: 1.5;\n}\n\n.card {\n  width: 90%;\n  max-width: 40rem;\n}", "body {\n  font-size: 1rem;\n}", language="css", tests=[{"test": "/font-size\\s*:[^;]*rem/.test(code)", "message": "Use rem for text size."}, {"test": "code.includes('line-height')", "message": "Set unitless line spacing."}, {"test": "code.includes('width') && code.includes('%')", "message": "Use a flexible percentage width."}]),
                build_lesson("The Box Model: Content, Padding, Border, and Margin", "start-css-box-model", "<h2>Every element is a rectangular box</h2><p>From the inside out, the box model is content, padding, border, and margin. Content is the text or image. Padding is space inside the border. The border is the visible edge. Margin is space outside the border, separating this box from neighbors.</p><h2>Understand sizing</h2><p>By default, width describes the content area, so padding and border add to the final width. <code>box-sizing: border-box</code> makes the declared width include content, padding, and border. Margin remains outside.</p><p>Change padding to create room inside a card, then margin to separate it from nearby content. This distinction is a useful debugging tool.</p>", "* { box-sizing: border-box; }\n\n.card {\n  width: 100%;\n  padding: 1.5rem;\n  border: 1px solid #cbd5e1;\n  margin: 1rem 0;\n}", ".card {\n  padding: 1.5rem;\n}", language="css", tests=[{"test": "code.includes('padding:')", "message": "Add inner spacing."}, {"test": "code.includes('border:')", "message": "Give the box a border."}, {"test": "code.includes('margin:')", "message": "Separate the box from neighbors."}, {"test": "code.includes('box-sizing')", "message": "Make sizing predictable."}]),
                build_lesson("Spacing and Sizing: Make a Simple Card", "start-css-spacing-card", "<h2>Use spacing to show relationships</h2><p>Use padding to keep text away from a card's edge. Use margin to separate the card from other blocks. In Flexbox or Grid, use <code>gap</code> for consistent space between children. Prefer a small set of intentional spacing values over unrelated numbers.</p><p>Use <code>max-width</code> to prevent a text panel becoming too wide. Center a narrower block with <code>margin-inline: auto</code>. Add <code>border-radius</code> for rounded corners when appropriate.</p><p>Change one value and notice what moves. If the background should fill a gap, use padding rather than margin.</p>", ".card {\n  width: 90%;\n  max-width: 36rem;\n  margin: 2rem auto;\n  padding: 1.5rem;\n  border-radius: 1rem;\n}", ".card {\n  padding: 1.5rem;\n}", language="css", tests=[{"test": "code.includes('.card')", "message": "Target the card class."}, {"test": "code.includes('max-width')", "message": "Keep the card from growing too wide."}, {"test": "code.includes('padding') && code.includes('margin')", "message": "Add inner and outer spacing."}]),
                build_lesson("Typography: Fonts, Size, and Line Spacing", "start-css-typography", "<h2>Typography affects comfort</h2><p><code>font-family</code> chooses a typeface. Include a fallback such as <code>Arial, sans-serif</code>. <code>font-size</code> sets text size; relative rem sizes respect user scaling. <code>line-height</code> adds room between lines. Around 1.5 is a useful starting point for body text.</p><p>Build hierarchy: a prominent page title, smaller section headings, and comfortable paragraph text. Limit long line lengths with a content container. Do not make important text tiny.</p><p>Good typography makes the content easier to understand, not just decorative.</p>", "body { font-family: Arial, sans-serif; line-height: 1.5; }\nh1 { font-size: 2.25rem; }\np { max-width: 65ch; }", "body { font-family: Arial, sans-serif; }", language="css", tests=[{"test": "code.includes('font-family')", "message": "Choose a font with a fallback."}, {"test": "code.includes('line-height')", "message": "Set comfortable line spacing."}, {"test": "code.includes('font-size')", "message": "Set a heading size."}]),
                build_lesson("Display and Normal Flow: Block, Inline, and None", "start-css-display-flow", "<h2>The browser lays elements out in normal flow</h2><p>Block elements such as paragraphs normally start on a new line and use available width. Inline elements such as links flow within text. <code>display</code> changes how an element participates in layout. <code>display: none</code> removes an item from layout, so do not use it to hide content people need.</p><p>Use normal flow for simple content before positioning. It adapts naturally when text wraps or the screen narrows. Flexbox and Grid help arrange groups of elements.</p><p>Change a display value in the preview and observe which surrounding items move.</p>", "p { display: block; }\na { display: inline; }\n.tag { display: inline-block; padding: 0.25rem 0.5rem; }", "p { display: block; }", language="css", tests=[{"test": "code.includes('display: block')", "message": "Keep paragraphs in block flow."}, {"test": "code.includes('display: inline')", "message": "Set an inline style for links."}, {"test": "code.includes('inline-block')", "message": "Create an inline-block tag."}]),
                build_lesson("Flexbox: Align Items in One Direction", "start-css-flexbox", "<h2>Flexbox arranges items along one dimension</h2><p>Apply <code>display: flex</code> to a parent. Its direct children become flex items. By default, they line up in a row. Set <code>flex-direction: column</code> to stack them. Use <code>gap</code> for even space, <code>justify-content</code> along the main axis, and <code>align-items</code> across the cross axis.</p><p>The main axis follows flex direction. Use <code>flex-wrap: wrap</code> when items should move to another line rather than become too narrow.</p><p>Flexbox belongs on the parent whose children you want to arrange.</p>", ".cards {\n  display: flex;\n  flex-wrap: wrap;\n  align-items: center;\n  gap: 1rem;\n}", ".cards {\n  display: flex;\n}", language="css", tests=[{"test": "code.includes('display: flex')", "message": "Make the parent a flex container."}, {"test": "code.includes('gap:')", "message": "Add consistent space between items."}, {"test": "code.includes('flex-wrap')", "message": "Allow items to wrap."}]),
                build_lesson("Grid: Arrange Content in Rows and Columns", "start-css-grid", "<h2>Grid is a two-dimensional layout tool</h2><p>CSS Grid controls rows and columns. Set <code>display: grid</code> on the parent, then define columns with <code>grid-template-columns</code>. <code>repeat(2, 1fr)</code> creates two equal flexible columns. Use <code>gap</code> between rows and columns.</p><p>Grid works well for card collections and aligned page regions. For one-direction alignment, Flexbox may be simpler. The tools complement each other.</p><p>Start with one column on narrow screens and add columns only when there is room.</p>", ".features {\n  display: grid;\n  grid-template-columns: repeat(2, 1fr);\n  gap: 1rem;\n}", ".features {\n  display: grid;\n}", language="css", tests=[{"test": "code.includes('display: grid')", "message": "Make the parent a grid container."}, {"test": "code.includes('grid-template-columns')", "message": "Define the columns."}, {"test": "code.includes('gap:')", "message": "Space the grid items."}]),
                build_lesson("Responsive CSS: Mobile-First Layout and Media Queries", "start-css-responsive-design", "<h2>Responsive pages adapt to available space</h2><p>Start with a layout that works in a narrow viewport, then enhance it for wider screens. Flexible widths, max-width, wrapping, and Grid can adapt without device-specific assumptions.</p><h2>Media queries</h2><p>A media query applies styles only when a condition matches. For example, <code>@media (min-width: 700px)</code> applies when the viewport is at least 700 CSS pixels wide. Put the small-screen rule outside the query, then wider-screen overrides inside.</p><ol><li>Make content fit a narrow screen.</li><li>Resize the preview and look for overflow.</li><li>Add a breakpoint only when content needs more columns.</li><li>Test below and above the breakpoint.</li></ol><p>Design for the available space, not a named phone model.</p>", ".cards { display: grid; grid-template-columns: 1fr; gap: 1rem; }\n@media (min-width: 700px) {\n  .cards { grid-template-columns: repeat(2, 1fr); }\n}", ".cards { display: grid; grid-template-columns: 1fr; }", language="css", tests=[{"test": "code.includes('display: grid')", "message": "Use a flexible grid layout."}, {"test": "code.includes('@media') && code.includes('min-width')", "message": "Add a wider-screen query."}, {"test": "code.includes('grid-template-columns')", "message": "Set the column layout."}]),
                build_lesson("Keyboard Focus, Contrast, and Reduced Motion", "start-css-accessibility", "<h2>Make the interface usable by more people</h2><p>Keep text and backgrounds distinguishable. Keyboard users need a clear focus indicator. Use <code>:focus-visible</code> with an outline; do not remove the browser focus style without a visible replacement.</p><p>Motion can cause discomfort. Respect the system preference with <code>@media (prefers-reduced-motion: reduce)</code> and reduce or remove optional animation.</p><p>Test using only Tab. Can you see which item is active? Check contrast rather than relying on taste alone.</p>", "a:focus-visible { outline: 3px solid #2563eb; outline-offset: 3px; }\n@media (prefers-reduced-motion: reduce) {\n  *, *::before, *::after { animation-duration: 0.01ms; }\n}", "a:focus-visible { outline: 3px solid #2563eb; }", language="css", tests=[{"test": "code.includes(':focus-visible') && code.includes('outline')", "message": "Show keyboard focus clearly."}, {"test": "code.includes('prefers-reduced-motion')", "message": "Respect reduced-motion preferences."}]),
            ],
        },
        {
            "title": "Build Your First Complete Web Page",
            "lessons": [
                build_lesson("Plan a Page Before You Code", "start-project-plan-page", "<h2>Plan before styling</h2><p>Choose a topic you know: a hobby, favorite place, or small service. Decide what visitors need to understand and what action they might take. Sketch a title, introduction, two content sections, and a useful link.</p><h2>Build in layers</h2><ol><li>Write semantic HTML for the content and its meaning.</li><li>Check that headings form an outline and links make sense.</li><li>Add CSS for type, color, spacing, and responsive layout.</li><li>Test at narrow and wide viewport sizes.</li><li>Review keyboard focus, contrast, and spelling.</li></ol><p>Do not perfect everything at once. A working simple page is a better starting point than an unfinished complicated one.</p>", "<main>\n  <h1>My favorite place</h1>\n  <p>A short introduction to the place.</p>\n  <section><h2>Why I like it</h2><p>One useful detail.</p></section>\n</main>", "<main>\n  <h1>My favorite place</h1>\n  <p>A short introduction to the place.</p>\n</main>", tests=[{"test": "code.includes('<main') && code.includes('<h1')", "message": "Start with main content and its title."}, {"test": "code.includes('<section') && code.includes('<h2')", "message": "Add a titled section."}]),
                build_lesson("Final Check: Test, Improve, and Keep Learning", "start-project-final-review", "<h2>Review the result, not only the code</h2><ul><li><strong>Structure:</strong> is there one clear main heading and meaningful sections?</li><li><strong>Content:</strong> are paragraphs readable, links descriptive, and images given appropriate alt text?</li><li><strong>Appearance:</strong> is text readable and spacing consistent?</li><li><strong>Responsive behavior:</strong> does the page fit a narrow screen without horizontal scrolling?</li><li><strong>Accessibility:</strong> can you navigate with Tab and see focus? Is contrast sufficient?</li><li><strong>Files:</strong> are project files clearly named and saved?</li></ul><p>When something is wrong, change one thing, refresh, and check again. Use browser tools and reliable documentation to investigate. Learning web development is ongoing practice, not a test of memorization.</p>", "<ul>\n  <li>Check page structure</li>\n  <li>Resize the preview</li>\n  <li>Test keyboard navigation</li>\n  <li>Save your work</li>\n</ul>", "<ul>\n  <li>Check page structure</li>\n  <li>Resize the preview</li>\n</ul>"),
            ],
        },
    ]
    # The requested course begins with learning to type and read HTML, not general
    # computer literacy. Keep the HTML/CSS/project path as its actual curriculum.
    return curriculum[1:]
